CREATE OR REPLACE FUNCTION public.calculate_trend_str(curr_val double precision, prev_val double precision)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  pct FLOAT;
BEGIN
  IF prev_val IS NULL OR prev_val = 0 THEN
    IF curr_val > 0 THEN
      RETURN '+100.0%';
    ELSE
      RETURN '+0.0%';
    END IF;
  END IF;
  pct := ((curr_val - prev_val) / prev_val) * 100.0;
  IF pct >= 0 THEN
    RETURN '+' || to_char(pct, 'FM990.0') || '%';
  ELSE
    RETURN to_char(pct, 'FM990.0') || '%';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.format_duration(seconds_val double precision)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  minutes INT;
  seconds INT;
BEGIN
  IF seconds_val IS NULL OR seconds_val <= 0 THEN
    RETURN '0s';
  END IF;
  minutes := floor(seconds_val / 60);
  seconds := round(seconds_val::numeric % 60);
  IF minutes > 0 THEN
    RETURN minutes || 'm ' || seconds || 's';
  END IF;
  RETURN seconds || 's';
END;
$function$

CREATE OR REPLACE FUNCTION public.format_time_ago(ts timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  diff INTERVAL;
  seconds INT;
  minutes INT;
  hours INT;
  days INT;
BEGIN
  diff := now() - ts;
  seconds := floor(extract(epoch from diff));

  IF seconds < 60 THEN
    RETURN 'Just now';
  END IF;

  minutes := seconds / 60;
  IF minutes < 60 THEN
    RETURN minutes || 'm ago';
  END IF;

  hours := minutes / 60;
  IF hours < 24 THEN
    RETURN hours || 'h ago';
  END IF;

  days := hours / 24;
  IF days = 1 THEN
    RETURN 'Yesterday';
  END IF;
  IF days < 7 THEN
    RETURN days || 'd ago';
  END IF;

  RETURN to_char(ts, 'Jan DD, YYYY');
END;
$function$

CREATE OR REPLACE FUNCTION public.get_analytics_browsers(range_filter text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  st TIMESTAMP WITH TIME ZONE;
  pst TIMESTAMP WITH TIME ZONE;
  nt TIMESTAMP WITH TIME ZONE;
  total_count FLOAT := 0.0;
  res JSONB;
BEGIN
  SELECT start_time, prev_start_time, now_time INTO st, pst, nt FROM public.get_timerange_bounds(range_filter);

  SELECT COUNT(*)::float INTO total_count FROM public.visitor_sessions WHERE created_at >= st AND created_at <= nt;

  IF total_count = 0 THEN
    total_count := 1.0;
  END IF;

  SELECT jsonb_agg(jsonb_build_object(
    'name', browser,
    'percentage', ROUND((count::float / total_count * 100)::numeric, 0)
  )) INTO res
  FROM (
    SELECT COALESCE(browser, 'Other') as browser, COUNT(*) as count
    FROM public.visitor_sessions
    WHERE created_at >= st AND created_at <= nt
    GROUP BY browser
    ORDER BY count DESC
    LIMIT 5
  ) b;

  RETURN COALESCE(res, '[]'::jsonb);
END;
$function$

